def solution(lst):
    """Given a non-empty list of integers, return the sum of all of the odd elements that are in even positions."""    

    # Initialize result as zero (default value) 
    res = 0  

    for i in range(len(lst)):       
          if lst[i] %2 != 0 and i%2 == 1 :     
              res += lst[i]    

    return res # or you can raise an exception as needed  e.g., ValueError("No odd numbers in even positions")  
